   && hasPullbackBetween(swingHighs[0], swingHighs[1]);

dipLow = lowestLowBetween(swingHighs[1].barIndex, swingHighs[0].barIndex); // the pullback low between the two tops
isValidShortStopEntry = open[0] > (dipLow - entryTick) && low[0] <= (dipLow - entryTick);
enterShortAtStop = isDoubleTop[1] && isValidShortStopEntry;

