pushes = lastThreeCounterTrendPushes(direction = UP); // [leftShoulder, head, rightShoulder] price extremes
isHeadAndShouldersTop = pushes[1].price > pushes[0].price && pushes[1].price > pushes[2].price
   && abs(pushes[0].price - pushes[2].price) <= shoulderSymmetryTolerance;
necklinePrice = trendLineValue(lineThrough(dipBetween(pushes[0], pushes[1]), dipBetween(pushes[1], pushes[2])), currentBarIndex);

patternBrokeDownBar = (isDoubleTop[k] || isHeadAndShouldersTop[k]) && close[k] < breakoutLevel[k]; // the neckline or dip low broke on some recent bar k
failedToFollowThrough = barsSinceBreakout <= maxFollowThroughBars && close[0] > breakoutLevel;
// enter with the larger (bull) trend once the failed breakout closes back above the level
isFailedBreakoutSignal = failedToFollowThrough && close[0] > open[0];
enterLongNextBarOpen = isFailedBreakoutSignal;

patternHeight = patternHighExtreme - patternLowExtreme;
measuredMoveTarget = breakoutPrice + patternHeight;
exitLongAtTarget = high[0] >= measuredMoveTarget;
